UPDATE companies SET description='Majors Plastics Inc. was founded in 1953 by Ben Pfeiffer and Eli Dahir in Omaha, Nebraska. The company relocated to its current Plant One location in 1968 and became a 100% employee-owned ESOP in 2013 after expanding the plan from its initial adoption in 1993.

The company operates four molding facilities across the United States and Mexico, specializing in precision injection molding, overmolding, insert molding, two-shot molding, and ISO Class-7 cleanroom molding. Its Omaha campus spans over 300,000 square feet and houses more than 120 molding machines, while the Reynosa, Mexico facility adds 128,000 square feet with 36 machines. Approximately 500 employees support high- and medium-volume production, complemented by assembly and secondary services such as ultrasonic welding, heat staking, pad printing, and custom packaging.

Longstanding customers include 3M, which has recognized the company multiple times with its Supplier of the Year Award, and Becton Dickinson (BD), which named it a Supply Chain Excellence Supplier of the Year. The firm secured its first medical products customer in 1985 and has since diversified into energy-related components and rigid computer disc preparatory operations.

The company emphasizes personalized customer relationships from initial design concept through finished product, providing engineering support throughout mold design and manufacturing. Its quality system is built on ISO 9001:2015 registration, statistical process control, and C=0 sampling plans to meet customer AQL levels as low as 0.040.', certifications=ARRAY['ISO 9001:2015','ISO 14644-1 Class 7']::text[], profile='{"capabilities": ["Injection Molding", "Overmolding", "Insert Molding", "Two-Shot Molding", "ISO Class-7 Cleanroom Molding", "Assembly", "Ultrasonic Welding", "Heat Staking", "Manual Assembly", "Pad Printing", "Heat Stamping", "Painting", "Custom Packaging", "Product Particle-Contamination Testing", "Engineering Support", "Tool-room Support", "Mold Repair and Maintenance", "Robotics & Automation"], "industries": ["Medical Devices", "Pharmaceutical", "Health & Safety", "Energy", "Consumer Electronics", "Tableware", "Industrial Manufacturing"], "materials": [], "equipment": ["Zeiss Coordinate Measuring Machines", "OGP Smartscopes (Flash 500 and desktop)", "Optical Comparators", "Spectrophotometers (Perkin Elmer and Hunter handheld)", "Zeiss Digital Microscope System", "Hazegard Transparency Testers", "Gauge Blocks", "Micrometers", "Height Gauges", "Calipers", "Granite Plates", "Angle Blocks", "Melt Flow Indicators", "Moisture Analyzers"], "volume": "High and medium volume", "lead_time": "", "tolerances": "", "built_on": ["100% employee-owned ESOP structure", "ISO Class-7 cleanroom molding with laminar HEPA-controlled airflow from molding to packaging", "Real-time ASTM E 2090 particle contamination testing and packaging", "Over 300,000 sq ft of manufacturing space in Omaha with 120+ injection molding machines", "Four molding facilities across the U.S. and Mexico"], "facts_used": ["Founded 1953 by Ben Pfeiffer and Eli Dahir -> /about", "100% employee-owned ESOP since 2013 -> /about", "Four molding facilities in U.S. and Mexico -> /", "Over 300,000 sq ft in Omaha with 120+ molding machines -> /about", "128,000 sq ft in Reynosa, Mexico with 36 molding machines -> /about", "Approximately 500 employees -> /about", "ISO 9001:2015 certified -> /quality", "ISO Class-7 cleanroom molding per ISO 14644 -> /", "Customers include 3M and BD -> /about", "Injection molding, overmolding, insert molding, two-shot molding -> /about", "Assembly services: ultrasonic welding, heat staking, pad printing, painting -> /about", "Quality equipment: Zeiss CMM, OGP Smartscopes, optical comparators -> /quality", "ASTM E 2090 particle contamination testing -> /"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "World Class Custom Injection Molder and Contract Manufacturing USA", "founded_year": "1953", "employee_count": "500", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Employee-owned"]}'::jsonb, updated_at=now() WHERE slug='majors-plastics-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Maker Shop Boise operates a community woodworking facility in Boise, Idaho. The shop provides members with access to professional-grade tools, free training, and a collaborative workspace designed to help people finish projects without the hassle of maintaining a personal shop.

The facility includes community workstations available first-come, first-served, plus a CNC room and epoxy room that can be reserved in advance. Equipment includes an Axiom AR8 Pro V5 CNC machine alongside a full suite of well-maintained hand and power tools, all housed in a climate-controlled space. Free safety and operation training is included with every membership, and classes cover specific tools and techniques.

The shop serves individual woodworkers, hobbyists, and makers who lack space or budget for their own equipment. Customers range from beginners building birdhouses to experienced craftspeople constructing cabinets, all supported by a team of mentors and coaches with collective decades of experience. The community aspect encourages peer learning and project inspiration.

The company differentiates itself by bundling tool access, training, and community into a single monthly membership, eliminating the need for large upfront tool purchases. A safety-first culture and the availability of mentors aim to give members confidence to tackle any project.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Woodworking", "CNC machining", "Epoxy work", "Safety and operation training", "Woodworking classes", "Mentorship and coaching", "Community workspace access", "Tool access (hand and power tools)", "Project reservation system (CNC room, epoxy room)"], "industries": ["Woodworking"], "materials": [], "equipment": ["Axiom AR8 Pro V5 CNC"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Free safety and operation training included with membership", "Access to professional-grade tools including Axiom AR8 Pro V5 CNC", "Climate-controlled facility with well-maintained equipment", "Community of mentors and coaches with collective 200+ years experience", "Membership includes full suite of tools (no need to purchase own)"], "facts_used": ["Location: Boise, Idaho -> db", "Website: makershopboise.com -> db", "Community workstations, CNC room, epoxy room -> /", "Axiom AR8 Pro V5 CNC machine -> /", "Free safety and operation training included -> /", "Day pass $99, classes, membership -> /", "Climate-controlled facility -> /", "Well-maintained, sharp, high quality tools -> /", "Mentors/coaches with 200+ years collective experience -> /", "Serves woodworkers, hobbyists, makers -> /", "Projects from birdhouses to cabinets -> /", "Safety-first culture -> /", "Membership includes full suite of tools -> /", "Company type: community workshop/makerspace -> /"], "company_type": "Other", "makes_products": "no", "type_evidence": "Get access to quality tools, free training, and fun classes.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tag