UPDATE companies SET description='Mann Solar operates from Lancaster, Kentucky, as an American-owned solar installation and product company. The firm provides NABCEP-certified solar installations for residential and commercial customers, along with a curated selection of panels, batteries, racking, and accessories.

Its product portal features German-engineered UZ Energy server-rack batteries with UL9540A certification and CW Energy half-cut and bifacial modules. Mann Solar also publishes hands-on product reviews and installation overviews to guide purchasing decisions.

The company highlights the 30% federal tax credit and warns of rising costs due to tariffs on Chinese-made equipment, positioning its existing inventory as a cost advantage.

Mann Solar differentiates itself through NABCEP certification, direct grant-application support, and a focus on pre-tariff pricing for American-owned supply. The firm emphasizes hands-on testing and expert insights to ensure customers select reliable, high-performance components.', certifications=ARRAY['ISO 9001','ISO 14001']::text[], profile='{"capabilities": ["Residential solar installation (ground mount, roof mount)", "Commercial solar installation (ground mount, sloped roof)", "USDA REAP grant application service", "Solar product sales (panels, batteries, racking, inverters, accessories, DIY kits)", "Product testing and review publication", "Solar system design and consultation"], "industries": ["Residential solar", "Commercial solar", "Agricultural solar (USDA REAP)"], "materials": ["LiFePO4 battery cells", "Half-cut monocrystalline solar cells", "Dual-glass solar modules", "Aluminum racking systems"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["NABCEP-certified solar installations", "USDA REAP grant application assistance", "Hands-on product reviews and expert insights", "Pre-tariff pricing on American-owned inventory", "UL9540A-certified battery offerings"], "facts_used": ["Location: Lancaster, Kentucky -> db", "Certifications: ISO9001, ISO14001 -> db", "Services: Residential and commercial solar installation (ground mount, roof mount, sloped roof) -> /", "Service: USDA REAP Grant Application Service -> /, db", "Products sold: Solar panels, batteries, racking, inverters, accessories, DIY kits -> /", "Brands: UZ Energy Server Rack Battery (German-engineered, UL9540A certified), CW Energy 450W and 595W panels -> /", "NABCEP certified installations -> /", "American-owned -> /", "30% tax credit promotion -> /", "Tariff impact on pricing -> /", "Hands-on product reviews and expert insights -> /"], "company_type": "Installer / service company", "makes_products": "no", "type_evidence": "Certified Solar Product Installer... Residential Installation... Commercial Installation", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='mann-solar' AND approved AND profile IS NULL;
UPDATE companies SET description='Manual Woodworkers & Weavers was founded in 1932 by Tom Oates in Hendersonville, North Carolina, amid the region’s bustling textile industry. The privately owned company established itself in the mountains of western North Carolina as a maker of gift and decorative accessories.

The company produces a wide range of decorative items including pillows, throws, quilts, wall hangings, wind chimes, figurines, wall signs, candles, clocks, and walking sticks. Its catalog spans seasonal collections such as Christmas, Americana, and nautical themes, as well as licensed artwork from artists like Thomas Kinkade Studios, Nicky Boehme, and Lori Siebert. Operations include a wholesale division that serves retailers through a dedicated sign-in portal and a “Manual Margin Makers” program.

The website features a “For Our Florists” section and a store finder for end consumers, indicating a focus on brick-and-mortar gift shops and floral outlets.

The company emphasizes its long-standing presence and innovative approach in the decorative accessories sector, though specific differentiators beyond its heritage and artist partnerships are not detailed in public materials.', certifications=ARRAY[]::text[], profile='{"capabilities": [], "industries": ["Gift and decorative accessories", "Wholesale", "Floral"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Innovative force in the gift and decorative accessories industry", "Privately owned and operated since 1932", "Artist collaborations including Thomas Kinkade Studios and Nicky Boehme", "Wholesale program featuring Manual Margin Makers"], "facts_used": ["Founded in 1932 by Tom Oates -> db", "Privately owned company in Hendersonville, NC -> db", "Operates in gift and decorative accessories industry -> db", "Product categories include pillows, throws, wall hangings, wind chimes, figurines, wall signs, walking sticks, ceramics, canvas art -> /", "Wholesale division with retailer portal and Manual Margin Makers program -> /", "Artist collaborations with Thomas Kinkade Studios, Nicky Boehme, Lori Siebert, others -> /", "Serves florists and retail gift shops -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Tom Oates founded Manual Woodworkers and Weavers (MWW). Our privately owned company... quickly established itself as an innovative force in the gift and decorative accessories industry.", "founded_year": "1932", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='manual-woodworkers-weavers' AND approved AND profile IS NULL;
UPDATE companies SET description='Manufacturing Industries, Inc. was founded and incorporated in 1976 by Ronald Quillen in Alderson, West Virginia. Quillen had worked in electronics design, test, and manufacturing since the late 1950s before returning to his hometown to start the company.

The company provides full-service electronic contract manufacturing including automated surface-mount assembly (SMT), thru-hole printed circuit board assembly, prototype and turn-key production assembly, electrical and functional testing, wire harness and cable assemblies, conformal coating, and scheduled delivery. A dedicated prototype and medium-quantity SMT line achieves up to 13,000 placements per hour, with pick-and-place data generated on the fly from a circuit board and bill of materials. That data can then be transferred to high-speed production equipment for larger volumes.

Manufacturing Industries serves medical, military, commercial, industrial, automotive, OEM, and consumer-product customers. Its flexible, high-mix capability targets small- to medium-quantity runs, pre-production test builds, and evaluations, with a path to scale into production quantities.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Automated surface mount assembly (SMT)", "Thru-hole printed circuit board assembly", "Prototype assembly", "Turn-key production assembly", "Electrical and function testing", "Wire harness and cable assemblies", "Conformal coatings", "Scheduled delivery service"], "industries": ["Medical", "Military", "Commercial", "Industrial", "Automotive", "OEM", "Consumer products"], "materials": [], "equipment": ["SMT pick-and-place machine (13,000 placements/hour)"], "volume": "", "lead_time": "", "tolerances": "", "built_on": [], "facts_used": ["Founded 1976 by Ronald Quillen -> /", "Second-generation family-owned -> /", "Location: Alderson, West Virginia -> /", "Full-service electronic contract manufacturing -> /", "Services: SMT, thru-hole, prototype, turn-key, testing, wire harness, conformal coating, scheduled delivery -> /", "SMT machine 13,000 placements/hour -> /", "Industries: medical, military, commercial, industrial, automotive, OEM, consumer products -> /", "Prototype-to-production data portability -> /", "Founded year 1976 -> db", "Headquarters Alderson, West Virginia -> db"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "MII is a full service electronic contract manufacturing company.", "founded_year": "1976", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='manufacturing-industries-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Manufacturing Works operates from Laramie, Wyoming, where it was established in 2019 as the state’s designated NIST Manufacturing Extension Partnership (MEP) Center. The organization was created to help Wyoming manufacturers and producers of every size and type improve their top-line potential and bottom-line growth.

Its offerings span continuous improvement, cybersecurity, advanced manufacturing technologies, ISO and quality management, prototyping support, supply chain optimization, business excellence assessment, and workforce development and training. Specific expertise includes additive manufacturing implementation, AR/VR integration, automation planning, CRM/ERP deployment, IoT education, and lean Six Sigma deployment. Services are matched to each client through a detailed assessment process.

The center serves manufacturers across Wyoming, with documented engagements ranging from oilfield service firms such as Integrated Well Services, Inc., to wastewater treatment specialists like TITUS Wastewater Solutions, community makerspaces including Maker Space 307, and industrial firms such as Pertech Industries, Inc. and Red River, LLC.

